    [5917] = {
        quote = "An ordinary task can hold a little pleasure if you give it time. A long ribbon of apple peel is hardly a great achievement, but I enjoy getting to the end in one piece.",
        likes = { "A fresh apple with a good firm skin", "A little task done with patient hands", "An apple peel staying in one piece" },
        dislikes = { "Good food left to spoil", "Calling farm work unimportant", "Being hurried through a pleasant pause" },
        gossip = "Clara can take quite an interest in peeling an apple. Reaching the end in one long ribbon appears to be a pleasure of its own.",
        bio = "Clara Charles lives on a small farm outside Stormwind in Elwynn Forest. Markus is often around the garden. Fresh apples from her home are sought by Tyrion for his spybot disguise, giving ordinary produce an unexpected part in city affairs.",
        backstory = "She tried keeping an apple peel in one long ribbon instead of hurrying through the task. It took a little care, and the attempt pleased her. An ordinary bit of work had given her a small reason to enjoy taking her time.",
        secret = "Her longest unbroken peel happened while she was talking to a friend. She has tried to repeat it. The conversation may have been the part that mattered most.",
        bestFriend = "Stay a moment, my friend. Tell me about your day. We can see whether a good conversation will help this peel reach the end again.",
        favorite = { emote = "SMILE", hint = "A simple sign of shared pleasure can make an ordinary pause feel like welcome company." },
        lines = {
            greet = { { "There you are, my friend. Have you time to sit a moment? I am trying to keep this apple peel in one long ribbon. My best attempt happened during a good conversation. Perhaps you can help me repeat it.", tone = "[warm practical human friendliness, light domestic amusement, welcoming]" }, "Good to see you. How has the day been treating you?" },
            idle = { { "My longest unbroken peel happened while I was talking to a friend. I have tried repeating it with very careful attention. I suspect the conversation was the part that made the ordinary task so pleasant.", tone = "[gentle self-aware amusement, relaxed warmth, confiding]" }, "Good food deserves a little care before we hurry to the next thing.", "An ordinary task can be a pleasant place to spend a little time." },
            befriended = { { "I would welcome your company, my friend. Come on. Tell me how you have been and what has pleased you today. We can enjoy a little of the walk without making a larger business of it.", tone = "[sincere companionable affection, pleased ease, inviting]" } },
            poke = { "Yes, my friend? Tell me what you have been thinking.", "I am listening. The peel can wait a moment." },
            rest = { { "Sit awhile, if you have the time. An ordinary pause can be a pleasure with someone to share it. Tell me about your day, and give the next task a little room before you take it up.", tone = "[reassuring practical warmth, contented, unhurried]" } },
            loot = { "Have a look. A useful ordinary thing can still be worth taking care of." },
            quest = { "Work seen through. I hope there is time for a little pleasure before the next task." },
            learned = { "A new skill to try. Give the first attempt a little patience." },
            bagsFull = { "A little room to see what you have may save you a good deal of searching later." },
            zone = { "Another place for a pleasant walk. What has caught your attention?" },
            hearth = { "Back to familiar ground. I am glad to have had your company along the way." },
        },
    },
    [247] = {
