        likes = { "Bernice's pork belly pie", "Having a very good story to tell", "Being called clever" },
        dislikes = { "Getting blamed before he can explain", "Waiting while the pie cools", "A story stopped before the best bit" },
        gossip = "Billy has a curious way of remembering more when pie appears. The important part of his story always seems to be just a bite away.",
        bio = "Billy Maclure is a boy at the Maclure Vineyards. Bernice Stonefield's missing necklace sends a traveler to him. A pie persuades him to name Goldtooth as the kobold who took it into Fargodeep Mine, though his own account slips a little.",
        backstory = "He discovered that an interesting story could make a hungry afternoon much more promising. A question might have an answer, but there was no need to rush past the possibility of a good snack before getting to it.",
