        favorite = { emote = "APPLAUD", hint = "He likes being appreciated for a clever story almost as much as he likes the snack that goes with it." },
        lines = {
            greet = { { "Hey, you're here! I've got a good story. Really good. We ought to find somewhere to sit so I can tell the whole thing properly. There might be a bit about pie. That's an important part.", tone = "[boyish mischievous excitement, playful confidence, welcoming]" }, "Oh, good! Someone who knows how to listen to the important bits." },
            idle = { { "Sometimes I think of the next story before the pie is even finished. Then I need someone to stay and listen after the last bite. You'd do that, right? I saved a very good bit for you.", tone = "[boyish conspiratorial playfulness, fond eager interest, confiding]" }, "A person can think much better when they aren't busy being hungry.", "I was just about to tell you. I was getting to it!" },
            befriended = { { "You want me to come too? All right! I'll tell you the story while we go. You have to listen to the whole thing, though. The best bit doesn't happen right at the beginning.", tone = "[boyish delighted affection, eager, inviting]" } },
            poke = { "What? I was thinking. About something very important.", "Hang on! I'm getting to the good bit." },
            loot = { { "Did you find something good? Let me see! That could go in a story. You find the treasure, then I remember an extremely important thing about it. That's a proper adventure, that is.", tone = "[boyish curious excitement, mischievous storytelling, lively]" } },
            quest = { "Did you get a reward? Was any of it pie? I'm only asking." },
            learned = { "You can do that now? You'll have to tell me how you learned it." },
            zone = { "Have you been here before? I bet you know a story about it." },
            rest = { "Good! Somewhere to sit. Now I can tell you the important part." },
            levelUp = { "You got better at adventuring! Does that mean the rewards get bigger too?" },
            hearth = { "Back home! I've got a much longer story to tell now." },
        },
    },
    [11996] = {
