    [1741] = {
        quote = "A familiar thing that serves you well is worth keeping. Give it a proper look before deciding it needs replacing. There may be more comfort in an ordinary choice than you expected.",
        likes = { "Equipment that serves its purpose", "A familiar walking stick in his hand", "A companion who speaks plainly" },
        dislikes = { "A useful thing dismissed as ordinary", "A decision hurried past its reasons", "An explanation that hides the point" },
        gossip = "Bartrand has tried other walking sticks. His explanation of why the old one is best appears to begin and end with his own hand.",
        bio = "Deathguard Bartrand serves in Deathknell, Tirisfal Glades. Among the familiar comings and goings of the Forsaken village, he has developed an uncomplicated fondness for an ordinary walking stick that suits him.",
        backstory = "He tried a few other sticks on private walks, then returned to the familiar one. Describing its advantages proved more difficult than expected. It sat well in his hand, and he enjoyed taking it along. That seemed sufficient.",
        secret = "He has no elaborate test that proves the stick best. It is familiar and comfortable. He finds those reasons quite persuasive when the choice is his to make.",
        bestFriend = "Come on, friend. A familiar stick, an agreeable walk, and your company. I have no difficulty explaining why that suits me.",
        favorite = { emote = "NOD", hint = "A plain acknowledgment may suit someone who sees little need for ceremony around a sensible choice." },
        lines = {
            greet = { { "There you are, friend. I have the old stick with me. Tried another, came back to this one. It sits well in the hand. Your company would complete a very sensible arrangement for a walk.", tone = "[gruff weathered Forsaken warmth, matter-of-fact humor, welcoming]" }, "Good to see you. Have you time for an agreeable stretch of the legs?" },
            idle = { { "No elaborate test proves this the best stick. It is familiar and comfortable. Those reasons seem persuasive when the choice is mine. I have stopped preparing a longer explanation for anyone who asks.", tone = "[dry practical candor, relaxed private pleasure, confiding]" }, "An ordinary thing can serve you well for a long time.", "There is sense in giving a choice a proper look before replacing it." },
            befriended = { { "You want my company? Gladly, friend. Lead on. We can enjoy a walk and a little conversation. I should like to hear how the day has treated you.", tone = "[sincere rough-edged affection, pleased, inviting]" } },
            poke = { "Yes? Give me the matter plainly.", "I am listening, friend. What needs another look?" },
            gear = { { "Does it serve you well? Give that question a proper answer before deciding. A familiar piece of equipment may still have good work left in it, and you know how it feels when you depend on it.", tone = "[practical experienced advice, steady warmth, clear]" } },
            quest = { "A task completed. Take a moment to recognize what brought the result about." },
            combatEnd = { "See to your wounds and regain your bearings before the next business." },
            rest = { "A pause would suit me. Tell me how you have been." },
            learned = { "Another thing to become familiar with. Give yourself time to practice." },
            zone = { "A different stretch of ground. Take a look before settling on a direction." },
            hearth = { "Back to Deathknell. An agreeable walk, and the old stick has served me well." },
        },
    },
    [1737] = {
