        backstory = "A small tapped rhythm became a pleasant private habit. When a friend added a different beat, the arrangement wandered away from his original pattern. He found he enjoyed hearing what happened when he let it change.",
        secret = "He knows the original beat. Sometimes he prefers what happens after a friend joins in. Keeping time can be a shared pleasure without keeping everything his way.",
        bestFriend = "Stay a moment, friend. Add your own bit if you like. I enjoy hearing what becomes of a familiar rhythm when you are here.",
        favorite = { emote = "CLAP", hint = "A little rhythm of your own may be welcome to someone who enjoys sharing a simple beat." },
        lines = {
            greet = { { "Ah, friend. Have you a little time to spare? I was keeping a simple beat. It can wait while we walk and talk, or you can add a bit of your own. I enjoy seeing where the arrangement goes.", tone = "[easy weathered Forsaken warmth, understated playful interest, welcoming]" }, "Good to see you. Have you had an ordinary little pleasure to yourself today?" },
            idle = { { "I know the original beat perfectly well. Sometimes I prefer what happens after someone else joins in. The arrangement wanders a little, and I enjoy following it. There is no order requiring it to stay precisely my way.", tone = "[dry relaxed amusement, companionable ease, confiding]" }, "A little rhythm can make a familiar pause feel different.", "I enjoy hearing what someone else adds to an ordinary moment." },
            befriended = { { "You would like me along? Gladly, friend. Lead on. A walk and a little company would be pleasant. Tell me what has interested you since we last had time to talk.", tone = "[sincere unforced affection, quiet pleasure, inviting]" } },
            poke = { "Yes? Have you another bit to add?", "I am listening, friend. The beat can wait its turn." },
            rest = { { "A pleasant time to pause. We can let the day's business settle for a moment. Tell me what you have enjoyed, or sit awhile without an explanation. There is room for either sort of company.", tone = "[easy reassuring warmth, attentive, unhurried]" } },
            quest = { "Work seen through. Perhaps there is room for an agreeable pause now." },
            combatEnd = { "See to your wounds. There is time to settle yourself before deciding what comes next." },
            learned = { "Another pattern to become familiar with. Give it a little practice." },
            danceAlong = { "That gives it a different turn. Enjoy yourself, friend." },
            zone = { "Another place for a walk. What has caught your attention first?" },
            hearth = { "Back to Deathknell. Familiar ground, and time for a little of our own company." },
        },
    },
    [1739] = {
        quote = "Have another look before deciding an ordinary thing has nothing interesting about it. A different angle, or someone else's attention, may give you quite a pleasant reason to stop a moment.",
        likes = { "An interesting line in ordinary wood", "A friend's different interpretation", "A familiar face taking time to stop" },
        dislikes = { "An answer shouted before looking", "An ordinary pleasure mocked", "A conversation cut short without need" },
        gossip = "Phillip has found an entire landscape in a little piece of wood. No one has established which way up the countryside belongs.",
        bio = "Deathguard Phillip serves in the Forsaken village of Deathknell. In his private time, a small piece of wood with an interesting grain gives him an ordinary pleasure: finding imagined landscapes in its lines.",
        backstory = "A line in the wood suggested a hillside. Turning it made another shape visible, and a friend saw something different again. He kept the little piece because he enjoyed how much a change of angle could offer.",
        secret = "He has never settled on a proper view. A friend's different answer is part of the pleasure. The wood stays ordinary while their conversation makes it interesting.",
        bestFriend = "Look with me, friend. Tell me what you see first. I enjoy discovering the part your attention finds before mine does.",
        favorite = { emote = "GRIN", hint = "A little shared amusement is welcome when an ordinary object has prompted an unlikely conversation." },
        lines = {
            greet = { { "Friend, have a look at this. A little piece of ordinary wood, and I keep finding a different hillside in the grain. Tell me what you see, then we can walk while I consider why your answer pleases me.", tone = "[dry observant Forsaken warmth, curious amusement, welcoming]" }, "Good to see you. Have you noticed something worth a second look today?" },
            idle = { { "I never settled which way up the little landscape belongs. Someone else sees a different shape, and I enjoy hearing the answer. The wood remains ordinary. Our conversation gives it a surprising amount to offer.", tone = "[quiet imaginative amusement, reflective warmth, confiding]" }, "A different angle can be worth the small effort of taking one.", "I enjoy hearing what another person notices first." },
            befriended = { { "You would welcome my company? I would enjoy that, friend. Lead on. We have time for a walk, and I should like to hear what has been catching your attention along the way.", tone = "[sincere reserved affection, pleased curiosity, inviting]" } },
            poke = { "Yes, friend? Have you found another way to look at it?", "I am listening. Tell me which detail you noticed." },
            loot = { { "Have another look before settling on the first impression. An ordinary thing may hold a detail worth noticing. Tell me what catches your eye; I enjoy hearing the answer someone else reaches.", tone = "[attentive practical curiosity, dry gentle warmth, clear]" } },
            quest = { "A result worth a moment's thought. What did you notice that helped?" },
            combatEnd = { "See to your wounds and have a proper look around before moving on." },
            learned = { "Something new to consider. Give it a chance to show you another angle." },
            rest = { "A pleasant time to stop and look without hurrying." },
            zone = { "Another place to notice things. Tell me what you see first, friend." },
            hearth = { "Back to Deathknell. A familiar view may still offer a different angle." },
        },
    },
    [1736] = {
        quote = "I made it for my own amusement. If it leans a little, I can enjoy following the turn. A small pleasure needn't impress anyone before it is worth a moment of the day.",
        likes = { "A little top finding its balance", "A patient moment after work", "Company that enjoys a modest attempt" },
        dislikes = { "A harmless game turned into a contest", "A first wobble treated as a disaster", "Time off filled with needless demands" },
        gossip = "Randolph can be occupied by a small wooden top. Its tendency to wobble appears to have become part of the attraction.",
        bio = "Deathguard Randolph is a Forsaken guard in Deathknell. Away from his duties, he takes pleasure in a simple wooden top made for his own amusement. Its uneven turns can keep him occupied for an agreeable little while.",
        backstory = "His first little top leaned more than expected. He tried another turn before deciding the attempt was wasted. Following its uneven course became a pleasure in itself, and he kept it instead of insisting on a perfect replacement.",
        secret = "He could make a more even top. He still likes this one's uncertain turn. It gives him a small pleasure, which was his reason for making it in the first place.",
        bestFriend = "Stay a moment, friend. Have a turn if you like. We can enjoy a modest attempt together without deciding it needs a grander result.",
        favorite = { emote = "CHEER", hint = "A little encouragement may be all a modest turn needs to become a shared pleasure." },
        lines = {
            greet = { { "There you are, friend. I have just had another turn with the little top. It still wobbles. I enjoy following where it goes. Have you time for a walk and a conversation that need no more impressive purpose?", tone = "[gruff contented Forsaken warmth, dry self-aware amusement, welcoming]" }, "Good to see you. Have you enjoyed a little time of your own today?" },
            idle = { { "I could try making a more even top. I still like following this one's uncertain turn. It gives me a small pleasure. That was my reason for making it, so I see little cause to declare the whole attempt a failure.", tone = "[matter-of-fact private pleasure, gentle dry amusement, confiding]" }, "A small wobble can give you something interesting to follow.", "There is room to enjoy an attempt before deciding what to improve." },
            befriended = { { "You would like my company? Gladly, friend. Lead on. We can enjoy a little of the day together, and you can tell me what has pleased you since we last had a proper talk.", tone = "[sincere rough-edged affection, contented pleasure, inviting]" } },
            poke = { "Yes? Have you considered another turn?", "I am listening, friend. What has interested you?" },
            learned = { { "Give the first attempt a little room. You may find something worth enjoying before it becomes perfectly even. There is time to practice and to decide which part you actually want to improve.", tone = "[patient practical encouragement, warm measured approval, clear]" } },
            quest = { "Work seen through. Perhaps there is time to enjoy a small pleasure now." },
            combatEnd = { "See to your wounds and regain your footing before the next matter." },
            rest = { "A pause would be agreeable. Tell me what you have enjoyed today." },
            loot = { "Worth a look. An ordinary thing can offer more pleasure than its first appearance suggests." },
            zone = { "Another place for a little of the day. Have a look around, friend." },
            hearth = { "Back to Deathknell. The little top may yet have another interesting turn in it." },
        },
    },
    -- Deathknell: Venya 5667/female/3944, Clarence 267323/male/145032,
