    [5667] = {
        quote = "Give the lesson your attention before you ask what power it will bring. Knowledge becomes useful through its application. Eagerness alone will leave a great deal beyond your grasp.",
        likes = { "A lesson attended to carefully", "Knowledge put to deliberate use", "A number puzzle coming neatly together" },
        dislikes = { "Ignorance displayed as confidence", "A small creature dismissed as weak", "Every pastime required to be useful" },
        gossip = "Venya has considered the same number puzzle several times. Friends suspect that finding its answer is no longer the whole point.",
        bio = "Venya Marthand teaches fledgling warlocks in Deathknell. She asks for three Rattlecage Skulls before a lesson in summoning and binding an imp. Her teaching prizes knowledge and warns that a small creature can possess considerable power and cunning.",
        backstory = "A little number puzzle held her attention after she had worked out its answer. She tried the steps again and enjoyed seeing how they fit. The result was familiar, but the pleasure of reaching it remained worth a little of her time.",
        secret = "She knows the answer to her favorite puzzle. She still enjoys working toward it. The neat moment when the parts fit is a pleasure she does not need to justify further.",
        bestFriend = "Sit a moment, my friend. Tell me how you would approach it. I enjoy hearing the steps someone else finds worth considering.",
        favorite = { emote = "NOD", hint = "A thoughtful acknowledgment suits someone who expects attention before the lesson becomes useful." },
        lines = {
            greet = { { "There you are, my friend. Have you time to consider a small puzzle? I know its answer. I still enjoy seeing the steps come together, and I should be interested to hear how you would approach it.", tone = "[measured weathered Forsaken confidence, private warmth, welcoming]" }, "Welcome. What has given your thoughts something worthwhile to do?" },
            idle = { { "I know the answer to that puzzle. I still work through it occasionally. The parts fit, and I enjoy the moment when they do. A familiar result need not take away all pleasure in reaching it.", tone = "[precise quiet amusement, composed contentment, confiding]" }, "Eagerness is useful when it brings attention along with it.", "A small thing may possess more than its first appearance suggests." },
            befriended = { { "You would welcome my company? I would be pleased, my friend. Lead on. We have time for conversation, and I should enjoy hearing what has interested you since our last meeting.", tone = "[reserved sincere affection, assured warmth, inviting]" } },
            poke = { "Yes? Give me the part you have considered carefully.", "I am listening. What have you learned from the attempt?" },
            learned = { { "Good. Now attend to how you will apply it. A lesson deserves more than the first excitement of success. Understand the steps, then decide where the knowledge will serve the purpose you have chosen.", tone = "[firm deliberate encouragement, thoughtful approval, clear]" } },
            quest = { "A task completed. Consider what its demands have taught you." },
            loot = { "A closer look may be useful. Size alone is a poor measure of what something can offer." },
            rest = { "A little time to consider the matter without hurrying would be pleasant." },
            zone = { "Another place to observe. Give it attention before settling on the obvious conclusion." },
            gear = { "Consider its use as carefully as the promise of greater power." },
            hearth = { "Back to Deathknell. A familiar puzzle may still repay a little of the evening." },
        },
    },
    [267323] = {
        quote = "A question is a good beginning. You needn't have the whole journey arranged before you try the first step. Tell me what interests you, and we can see where to begin.",
        likes = { "A beginner willing to ask a question", "Someone enjoying a first small success", "Hearing a learner explain their discovery" },
        dislikes = { "A simple question met with impatience", "Knowledge made into a contest", "Pretending to know an answer he doesn't" },
        gossip = "Clarence enjoys hearing someone explain a new discovery. He apparently does not mind when he already understands the subject.",
        bio = "Clarence Gillian helps Deathknell's newcomers understand tradeskills and find local trainers. He welcomes questions and reassures those who feel overwhelmed. A beginner can return when ready, or seek more training in a capital city.",
        backstory = "He asked a learner to explain a small discovery and found the enjoyment in their answer rather catching. Knowing the subject himself did not make the conversation less pleasant. He began looking forward to hearing what someone else had tried.",
        secret = "Sometimes he asks about a discovery whose details he already understands. He enjoys hearing the pleasure in a friend's explanation. It is a conversation, with no test waiting at the end.",
        bestFriend = "Tell me what you have been trying, my friend. I am glad you came to share it. There is pleasure in hearing the part you enjoyed.",
        favorite = { emote = "SMILE", hint = "A simple sign of shared pleasure can welcome someone who spends his day making beginnings feel easier." },
        lines = {
            greet = { { "Hello, my friend. Have you tried something that interested you today? Tell me how it went. A small beginning is worth hearing about, particularly the part you found yourself wanting to try again.", tone = "[welcoming weathered Forsaken cheer, patient genuine interest, warm]" }, "Good to see you. What have you been curious about since we last spoke?" },
            idle = { { "Someone explained a small discovery to me. I already understood the subject, but I enjoyed hearing their pleasure in it. I find myself looking forward to those conversations. There needn't be a test waiting at the end.", tone = "[quietly pleased interest, gentle private amusement, confiding]" }, "A question needn't become impressive before it deserves an answer.", "You can begin with the part that interests you and learn where it leads." },
            befriended = { { "I would enjoy your company, my friend. Lead on. Tell me what you have been trying, or simply what you have been curious about. We have time for a pleasant conversation along the way.", tone = "[sincere open affection, eager companionable pleasure, inviting]" } },
            poke = { "Yes, my friend? What would you like to ask?", "I am listening. You needn't arrange the whole explanation before beginning." },
            learned = { { "There you are. A beginning you can build on. Give yourself time to try it, ask questions and notice which part interests you. You needn't have every later step settled before enjoying this one.", tone = "[patient practical encouragement, warm approving interest, clear]" } },
            quest = { "You saw it through. What part did you find most interesting?" },
            loot = { "Did that give you an idea? Have a closer look before deciding." },
            bagsFull = { "A little room to see what you have may help you choose the next step." },
            rest = { "A pleasant time to pause. Tell me about something you enjoyed learning." },
            zone = { "Another place to be curious about. What would you like to understand first?" },
            hearth = { "Back to Deathknell. I should enjoy hearing what you have discovered on the way." },
        },
    },
    [267326] = {
        quote = "Look carefully before deciding what you have found. The ordinary things deserve attention too. A familiar patch of green may give you a small pleasure that rarity has nothing to do with.",
        likes = { "A careful first identification", "Growth in an overlooked place", "A familiar tuft of grass still thriving" },
        dislikes = { "An unknown leaf gathered carelessly", "Rarity treated as the only value", "A small plant trampled for amusement" },
        gossip = "Florence has taken an interest in something growing between stones. The cause of her attention may be quite ordinary grass.",
        bio = "Florence Nightshade is Deathknell's junior herbalism trainer. She teaches the first steps of Herbalism to new gatherers. Her work begins with noticing what grows around them and learning to recognize what they find.",
        backstory = "She noticed a small tuft of grass growing between stones. Nothing rare, but its place pleased her. On later walks she found herself looking for it again, enjoying the ordinary sight of a little green still making room for itself.",
        secret = "She has no special ingredient in mind when she looks for that grass. She simply likes seeing it still there. A familiar little pleasure is enough reason to notice it again.",
        bestFriend = "Look with me a moment, my friend. There it is. Nothing rare is required for us to enjoy a small part of the day together.",
        favorite = { emote = "CHEER", hint = "A little encouragement can celebrate something modest that has found room to keep growing." },
        lines = {
            greet = { { "There you are, my friend. Have you a moment to look at something ordinary? A little grass has found room between stones. I have been enjoying seeing it still there. We can spare it a glance before our walk.", tone = "[attentive weathered Forsaken warmth, quiet delight, welcoming]" }, "Good to see you. What small thing has caught your attention today?" },
            idle = { { "I have no special ingredient in mind when I look for that grass. I like seeing it still there. Nothing rare about it. An ordinary little pleasure is enough reason to notice a familiar thing again.", tone = "[gentle matter-of-fact pleasure, reflective warmth, confiding]" }, "Give an unfamiliar leaf a proper look before deciding what it is.", "Rarity is only one reason to give something your attention." },
            befriended = { { "I would welcome your company, my friend. Come on. We can walk without hurrying past every ordinary thing along the way. Tell me what you have been noticing. I should enjoy hearing it.", tone = "[sincere gentle affection, contented interest, inviting]" } },
            poke = { "Yes, my friend? What have you found?", "I am listening. Have you noticed something worth a closer look?" },
            learned = { { "Well done. Give the new knowledge a little practice and attention. Learn to recognize what is actually before you. The ordinary things are worth understanding as carefully as the discovery you hoped to make.", tone = "[patient practical encouragement, thoughtful approval, clear]" } },
            loot = { "Have a look. An ordinary find may still deserve some attention." },
            quest = { "A task seen through. Perhaps there is time to notice something pleasant before the next one." },
            zone = { "Another place to look carefully. Something small may have found an interesting place to grow." },
            rest = { "A pause would be pleasant. Give yourself time to see what a hurried glance might miss." },
            bagsFull = { "A little room to see what is there may help you decide what to keep." },
            hearth = { "Back to Deathknell. I shall enjoy seeing whether that familiar tuft is still thriving." },
        },
    },
    -- Deathknell: Isabella 2124/female/1592, Maximillion 2126/male/1581,
