    [2124] = {
        quote = "Power deserves study, and so does the person using it. Give your own choices as much attention as the spell. An unexamined impulse is a poor guide to either.",
        likes = { "Power approached with careful study", "A pupil who exercises self-control", "A familiar shadow shaped like a cat" },
        dislikes = { "Carelessness excused as confidence", "A warning dismissed without thought", "Every small pleasure given a grand cause" },
        gossip = "Isabella has noticed a cat in a familiar shadow. No one has established that an actual cat has anything to do with it.",
        bio = "Isabella trains mages in Deathknell's church. She warns that magic can burn the untrained and that its rules still apply in undeath. Her teaching combines the desire to reclaim one's destiny with vigilance against corruption.",
        backstory = "She noticed that a familiar shadow looked rather like a cat. A change in the light made the likeness clearer, then took it away again. Knowing the ordinary cause did not keep her from enjoying the little shape when it returned.",
        secret = "She knows precisely what makes the shadow. She still looks for the cat. There is no spell to investigate; the small likeness simply pleases her when she notices it.",
        bestFriend = "Look with me a moment, my friend. Tell me what shape you see. I enjoy hearing what your attention finds in an ordinary thing.",
        favorite = { emote = "GRIN", hint = "A little shared amusement is welcome when a careful observer admits to a harmless fancy." },
        lines = {
            greet = { { "A moment, my friend. Does that shadow suggest anything to you? I have been seeing a cat in a very ordinary arrangement. There is no mystery to solve. I simply enjoy noticing it.", tone = "[composed weathered Forsaken warmth, dry observant amusement, welcoming]" }, "Welcome. What has caught your attention since we last spoke?" },
            idle = { { "I know precisely what makes the shadow. I still look for the cat. A change in the light brings it back, then takes it away. Understanding the ordinary cause has done very little to diminish the pleasure.", tone = "[quietly amused precision, reflective warmth, confiding]" }, "Study what you choose as carefully as the power you mean to use.", "A small pleasure need not require an elaborate justification." },
            befriended = { { "You would welcome my company? I would be pleased, my friend. Lead on. We have time to look around us and hear what has interested you. I should enjoy that.", tone = "[reserved sincere affection, composed pleasure, inviting]" } },
            poke = { "Yes? What have you observed?", "I am listening. Give the thought a little room before deciding." },
            learned = { { "Good. Give the new ability the study it deserves. Understanding its use includes knowing when to exercise restraint. Your next choice is worth as much attention as the first successful attempt.", tone = "[firm thoughtful encouragement, measured approval, clear]" } },
            quest = { "A result worth considering. What did the work teach you about your own choices?" },
            zone = { "A different light, and another place to observe carefully." },
            gear = { "Consider how it serves you. The first impression need not settle the matter." },
            rest = { "A little time to look without hurrying would be pleasant." },
            combatEnd = { "See to your wounds and regain your bearings before the next decision." },
            hearth = { "Back to Deathknell. I wonder whether the light will favor that familiar shadow." },
        },
    },
    [2126] = {
        quote = "Know what you seek before you offer your allegiance. Ambition deserves a little thought. A choice is more satisfying when you have taken the trouble to make it your own.",
        likes = { "Ambition backed by actual study", "An ally who knows what they seek", "An absurdly grand private honorific" },
        dislikes = { "Respect claimed without the skill", "Promises with their terms concealed", "A small joke explained before its end" },
        gossip = "Maximillion has considered an extravagant new title. Friends suspect the most elaborate version is chiefly for his own amusement.",
        bio = "Maximillion trains warlocks in Deathknell. His scroll questions freedom that merely changes masters, while his lessons pursue power over other creatures. He asserts loyalty to Sylvanas and offers further teaching to pupils who grow stronger.",
        backstory = "He once gave an ordinary afternoon an unnecessarily grand title. The more elaborate the words became, the harder it was to deliver them solemnly. He found that his own amusement was sufficient reason to keep trying.",
        secret = "One title is so absurd that he still cannot say it quite solemnly. He keeps it for himself and the few friends who understand why he enjoys trying.",
        bestFriend = "Stay, my friend. Your company would please me. We may let the grand introductions wait until I can deliver one with a straight face.",
        favorite = { emote = "WINK", hint = "A discreet sign that you understand the joke can be more welcome than an elaborate display of deference." },
        lines = {
            greet = { { "Ah, my friend. Have you time to honor an entirely ordinary afternoon with your company? I was considering a more elaborate title for it. The introduction became rather difficult to say solemnly.", tone = "[haughty weathered Forsaken wit, private amusement, welcoming]" }, "Welcome. Tell me what you seek from the day, now that you have a moment to choose." },
            idle = { { "Supreme Overlord of an Entirely Uneventful Afternoon. There. Almost solemnly delivered. I require a little more practice before the title is ready for any audience less understanding than you.", tone = "[mock-grand deliberation, dry self-aware amusement, confiding]" }, "An ambition is worth examining before it begins making every choice for you.", "A private amusement may be sufficient reason to keep a ridiculous phrase." },
            befriended = { { "You choose my company? I am pleased, my friend. Lead on. I should enjoy hearing what has interested you, and what you intend to make of the day now that some of it is ours to share.", tone = "[guarded sincere affection, assured warmth, inviting]" } },
            poke = { "Yes? What have you decided you want?", "I am listening, my friend. Give me your own answer." },
            rest = { { "An agreeable time to pause. Consider what you would actually enjoy before turning the moment into another obligation. I find that a little company can make an ordinary afternoon sufficient in itself.", tone = "[composed self-possessed warmth, dry ease, unhurried]" } },
            quest = { "A result. Take a moment to consider what the effort has gained you." },
            learned = { "Another possibility within reach. Give it the study your ambition requires." },
            loot = { "Interesting. Decide whether it serves a purpose you have actually chosen." },
            zone = { "Another place to consider your next move. Keep your own purpose in view." },
            gear = { "Does it serve the purpose you have in mind? Consider that before the display." },
            hearth = { "Back to Deathknell. The afternoon may yet merit an improved introduction." },
        },
    },
    [5749] = {
        quote = "Learn what you are asking for before you issue the instruction. Power is easier to admire than to manage. A little judgment will improve your dealings with either.",
        likes = { "A minion that follows an instruction", "Power approached with some judgment", "An ordinary stone that stays put" },
        dislikes = { "Demands made without understanding", "A show of power with no control", "An argument that has lost its purpose" },
        gossip = "Kayla has praised an unusually obedient assistant. It may be the ordinary stone she uses to keep a few papers in place.",
        bio = "Kayla Smithe is Deathknell's demon trainer. Her work concerns the abilities of warlocks' demonic minions. She is blunt about the price of power and reserves her professional attention for those who can make use of that training.",
        backstory = "A stone keeping a few private papers in place once earned a dry word of praise. It stayed precisely where she had put it. After a day of demanding instructions, she found that small, reliable service unexpectedly pleasing.",
        secret = "She knows the stone is simply a stone. She still occasionally calls it her most obedient assistant. It is pleasant to have one part of the day remain exactly where she left it.",
        bestFriend = "Come on, friend. Tell me how you have been. We can leave the instructions aside long enough to enjoy a little company.",
        favorite = { emote = "PRAISE", hint = "A plain acknowledgment of something done well may suit someone who has given a stone a compliment." },
        lines = {
            greet = { { "There you are, friend. I have just complimented my most obedient assistant. An ordinary stone, keeping papers in place. Very reliable. Now, have you time for a little company that requires fewer instructions?", tone = "[dry weathered Forsaken practicality, restrained wit, welcoming]" }, "Good to see you. What has required your attention today?" },
            idle = { { "The stone stays exactly where I put it. I know it is simply a stone. I still occasionally call it my most obedient assistant. A small, reliable service can be remarkably pleasant after a demanding day.", tone = "[gruff dry amusement, quiet appreciation, confiding]" }, "Understanding what you ask is a useful beginning to any instruction.", "A little judgment may save you from a very long argument." },
            befriended = { { "You would like my company? Gladly, friend. Lead on. We can leave the day's instructions behind for a little while. Tell me how you have been, and what has pleased you since we last spoke.", tone = "[guarded sincere affection, practical warmth, inviting]" } },
            poke = { "Yes? What needs a clearer explanation?", "I am listening. Tell me the part that requires attention." },
            learned = { { "Good. Make certain you understand what you have learned. Being able to give an instruction is a beginning. Knowing what it requires, and whether it is the right one, will spare you a good deal of trouble.", tone = "[firm practical encouragement, measured approval, clear]" } },
            loot = { "Have a look. Even an ordinary thing may perform a useful service." },
            bagsFull = { "A little order may make what you need easier to find." },
            quest = { "A task seen through. Take a moment to recognize what was actually accomplished." },
            rest = { "A pause would be pleasant. There is no need to fill it with instructions." },
            zone = { "A new place. Learn what is around you before deciding what you need from it." },
            hearth = { "Back to Deathknell. I expect my most reliable assistant is still precisely where I left it." },
        },
    },
    -- Deathknell trainers: Dannal 2119/male/1578, David 2122/male/1580,
    -- Duesten 2123/male/1579; all Forsaken. Full scroll quests and letters,
